schema_ddl:
CREATE TABLE FOLLOW (
    FOLLOWEE VARCHAR(255),
    FOLLOWER VARCHAR(255),
    PRIMARY KEY (FOLLOWEE, FOLLOWER),
    CHECK (FOLLOWEE <> FOLLOWER)
);

counterexample:
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A', 'B');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('B', 'A');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('A', 'C');
INSERT INTO FOLLOW (FOLLOWEE, FOLLOWER) VALUES ('C', 'A');

